import Foundation

// Re-posed hands (run 123+: distal gap close, inflated thumb): fingers posed per tool class by a 3-joint chain fit to the
// real handle radius (screwdriver/welder 12.5 mm, wrench shaft 6.5 mm), thumb chain solved
// by optimisation, palm/wrist from the baked pose. Quantised absolute vertex positions
// (UInt16 over min/span) in the same 8120-vertex topology as HandMeshAsset.
// Blob A (grip, squeeze) is here; blob B (roundGrip, roundSqueeze) is in HandPoseV2Round.swift.
enum HandPoseV2 {
    struct E { let name: String; let src: Int; let min: SIMD3<Float>; let span: SIMD3<Float>; let off: Int }
    static let entries: [E] = [
        E(name: "grip", src: 0, min: [-0.07109369, 0.02046371, -0.00130941], span: [0.08011505, 0.09103634, 0.06301886], off: 0),
        E(name: "squeeze", src: 0, min: [-0.07109055, 0.02046371, -0.00131563], span: [0.08011191, 0.09129266, 0.06301839], off: 48720),
        E(name: "roundGrip", src: 1, min: [-0.06936489, 0.02046512, -0.00596480], span: [0.07754782, 0.09215818, 0.06772699], off: 0),
        E(name: "roundSqueeze", src: 1, min: [-0.06936047, 0.02046510, -0.00601314], span: [0.07754345, 0.09272937, 0.06777597], off: 48720),
    ]
    static func has(_ name: String) -> Bool { entries.contains { $0.name == name } }
    private static let b64A: String = [
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        ""
    ].joined()
    private static let blobA: Data = Data(base64Encoded: b64A)!
    private static let blobB: Data = Data(base64Encoded: b64B)!
    static func verts(_ name: String, nv: Int) -> [Float]? {
        guard let e = entries.first(where: { $0.name == name }) else { return nil }
        let blob = e.src == 0 ? blobA : blobB
        guard blob.count >= e.off + nv * 6 else { return nil }
        var out = [Float](repeating: 0, count: nv * 3)
        blob.withUnsafeBytes { ptr in
            let q = ptr.baseAddress!.advanced(by: e.off).assumingMemoryBound(to: UInt16.self)
            for i in 0..<nv {
                out[i*3+0] = e.min.x + Float(q[i*3+0]) / 65535.0 * e.span.x
                out[i*3+1] = e.min.y + Float(q[i*3+1]) / 65535.0 * e.span.y
                out[i*3+2] = e.min.z + Float(q[i*3+2]) / 65535.0 * e.span.z
            }
        }
        return out
    }
}
